        "localizador": "L01"
      },
      {
        "fonte_id": "f_77c5d27cd0",
        "localizador": "L02"
      }
    ],
    "lacunas": [
      "A cobrança de extensão depende de o marco final ultrapassar D10; como o término novo é indeterminado, não se pode determinar o custo total exato."
    ],
    "motivo": "O custo inclui a cobrança adicional certa de 15000 centavos, mas eventual extensão contratual não pode ser calculada sem a data do marco final.",
    "unidade": "BRL_centavo"
  },
  "delta_centavos": {
    "estado": "direcao",
    "valor": null,
    "direcao": "aumento",
